新增文件 lib/campus-anchors.ts；具体入口为 registerExportAnchors、bindBrowserAnchors、CampusManipulation.tick 和 verifyCampusMotion。仅操作校园场景资产的锚点元数据与风关节显示姿态，不改材质或梁求解。导出前注册节点，浏览器加载后用同一份清单绑定；保留原节点名称，避免破坏现有 /foreground/i 选枝规则。逆变换使用完整世界矩阵，而不是只取逆旋转，因此也支持带缩放的父层级。

```ts
import * as THREE from 'three';

export type Axis = 'x' | 'z';
export type Anchor = {
  id: string;
  nodeName: string;
  role: 'lampBase' | 'trunkBase' | 'canopyTip';
  point: [number, number, number];
};
export type Drive = (
  dt: number, speed: number, mass: number, axis: Axis
) => void;

function requireThat(ok: boolean, message: string): asserts ok {
  if (!ok) throw new Error(message);
}

export function boundedResponse(
  old: number, target: number, dt: number, tau: number
): number {
  if (![old, target, dt, tau].every(Number.isFinite)) {
    throw new Error('boundedResponse requires finite inputs');
  }
  return dt <= 0 || tau <= 0 ? old : Math.min(
    Math.max(old, target),
    Math.max(Math.min(old, target), old + (target - old) * dt / (tau + dt))
  );
}

function named(root: THREE.Object3D, name: string): THREE.Object3D {
  const found: THREE.Object3D[] = [];
  root.traverse(n => { if (n.name === name) found.push(n); });
  requireThat(found.length === 1, `expected one named node: ${name}`);
  return found[0];
}

function validateManifest(manifest: Anchor[]): void {
  requireThat(manifest.length > 0, 'empty anchor manifest');
  requireThat(new Set(manifest.map(a => a.id)).size === manifest.length,
    'duplicate anchor IDs');
  // 当前交付采用一节点一锚点；需要多锚点时应显式扩展元数据结构。
  requireThat(new Set(manifest.map(a => a.nodeName)).size === manifest.length,
    'multiple anchors on one named node');
  for (const a of manifest) {
    requireThat(Boolean(a.id && a.nodeName), 'empty anchor ID/name');
    requireThat(a.point.length === 3 && a.point.every(Number.isFinite),
      `invalid local point: ${a.id}`);
    requireThat(['lampBase', 'trunkBase', 'canopyTip'].includes(a.role),
      `invalid role: ${a.id}`);
  }
}

export function registerExportAnchors(
  root: THREE.Object3D, manifest: Anchor[]
): Anchor[] {
  validateManifest(manifest);
  // 清单中的 nodeName 必须来自实际资产，不在此猜测基线节点名称。
  for (const a of manifest) {
    named(root, a.nodeName).userData.campus_anchor_id = a.id;
  }
  bindBrowserAnchors(root, manifest);
  return manifest.map(a => ({ ...a, point: [...a.point] }));
}

export function bindBrowserAnchors(
  root: THREE.Object3D, manifest: Anchor[]
) {
  validateManifest(manifest);
  root.updateMatrixWorld(true);
  const entries = new Map<string, {
    spec: Anchor; node: THREE.Object3D; base: THREE.Matrix4
  }>();
  for (const a of manifest) {
    const node = named(root, a.nodeName);
    const matching: THREE.Object3D[] = [];
    root.traverse(n => {
      if (n.userData.campus_anchor_id === a.id) matching.push(n);
    });
    requireThat(matching.length === 1 && matching[0] === node,
      `export/browser ID mismatch: ${a.id}`);
    entries.set(a.id, { spec: a, node, base: node.matrixWorld.clone() });
  }
  function entry(id: string) {
    const e = entries.get(id);
    requireThat(Boolean(e), `unregistered anchor: ${id}`);
    return e!;
  }
  function toLocal(id: string, world: THREE.Vector3): THREE.Vector3 {
    root.updateMatrixWorld(true);
    const m = entry(id).node.matrixWorld;
    requireThat(Math.abs(m.determinant()) > 1e-12, 'singular anchor transform');
    return world.clone().applyMatrix4(m.clone().invert());
  }
  function toWorld(id: string, local: THREE.Vector3): THREE.Vector3 {
    root.updateMatrixWorld(true);
    return local.clone().applyMatrix4(entry(id).node.matrixWorld);
  }
  function position(id: string): THREE.Vector3 {
    return toWorld(id, new THREE.Vector3(...entry(id).spec.point));
  }
  function assertFixed(epsilon = 1e-8): void {
    root.updateMatrixWorld(true);
    for (const e of entries.values()) {
      if (e.spec.role === 'canopyTip') continue;
      requireThat(e.node.matrixWorld.elements.every((v, i) =>
        Math.abs(v - e.base.elements[i]) <= epsilon),
      `fixed base moved: ${e.spec.id}`);
    }
  }
  return { entry, toLocal, toWorld, position, assertFixed };
}

export type Registry = ReturnType<typeof bindBrowserAnchors>;

export class CampusManipulation {
  private joints: {
    node: THREE.Object3D; rest: THREE.Quaternion; raw: THREE.Quaternion
  }[] = [];
  private gain = 1;
  private target = 1;

  constructor(
    root: THREE.Object3D,
    private anchors: Registry,
    private drive: Drive,
    private tau = 0.12
  ) {
    requireThat(Number.isFinite(tau) && tau > 0, 'invalid interaction tau');
    root.traverse(node => {
      if (node.userData.wind_joint === true) {
        this.joints.push({ node, rest: node.quaternion.clone(),
          raw: node.quaternion.clone() });
      }
    });
    requireThat(this.joints.length > 0, 'no wind joints registered');
  }

  private render(): void {
    for (const j of this.joints) {
      j.node.quaternion.copy(j.rest).slerp(j.raw, this.gain);
      j.node.updateMatrix();
    }
  }

  setTarget(value: number): void {
    requireThat(Number.isFinite(value), 'invalid amplitude');
    this.target = Math.max(0, Math.min(1, value));
  }

  // 用注册锚点的逆变换解释拾取位置；只控制变形幅度，不平移树基或灯基。
  dragAmplitude(id: string, world: THREE.Vector3, localTravel: number): void {
    const e = this.anchors.entry(id);
    requireThat(e.spec.role === 'canopyTip', 'base anchors are not draggable');
    requireThat(Number.isFinite(localTravel) && localTravel > 0,
      'invalid drag scale');
    const displacement = this.anchors.toLocal(id, world)
      .sub(new THREE.Vector3(...e.spec.point));
    this.setTarget(displacement.length() / localTravel);
  }

  checkpoint(): Readonly<{ gain: number; target: number }> {
    return { gain: this.gain, target: this.target };
  }

  // 在暂停的同一求解时刻可精确恢复显示幅度；不声称倒放梁的内部状态。
  rollbackAmplitude(saved: Readonly<{ gain: number; target: number }>): void {
    requireThat([saved.gain, saved.target].every(v =>
      Number.isFinite(v) && v >= 0 && v <= 1), 'invalid amplitude checkpoint');
    this.gain = saved.gain;
    this.target = saved.target;
    this.render();
  }

  tick(dt: number, speed: number, mass: number, axis: Axis): void {
    requireThat([dt, speed, mass].every(Number.isFinite), 'nonfinite drive');
    if (dt <= 0) return;
    // 求解前恢复原始梁姿态，防止显示包络反馈进原求解器。
    for (const j of this.joints) {
      j.node.quaternion.copy(j.raw);
      j.node.updateMatrix();
    }
    this.drive(dt, speed, mass, axis);
    for (const j of this.joints) j.raw.copy(j.node.quaternion);
    this.gain = boundedResponse(this.gain, this.target, dt, this.tau);
    this.render();
  }
}

export type MotionRig = {
  anchors: Registry;
  interaction: CampusManipulation;
  tipId: string;
};

// 可由浏览器/导出资产验收程序调用；factory 必须每次创建全新求解状态。
export function verifyCampusMotion(
  factory: () => MotionRig,
  options = { dt: 1 / 60, actionSeconds: 2, releaseSeconds: 10,
    minimumMotion: 1e-4, releaseFraction: 0.1 }
) {
  const result: { axis: Axis; peak: number; remaining: number }[] = [];
  for (const axis of ['x', 'z'] as const) {
    const { anchors, interaction, tipId } = factory();
    const initial = anchors.position(tipId);
    let peak = 0;
    let axialPeak = 0;
    const frame = (speed: number) => {
      interaction.tick(options.dt, speed, 0, axis);
      anchors.assertFixed();
      return anchors.position(tipId).sub(initial);
    };
    for (let i = 0; i < Math.ceil(options.actionSeconds / options.dt); i++) {
      const d = frame(1);
      peak = Math.max(peak, d.length());
      axialPeak = Math.max(axialPeak, Math.abs(d[axis]));
    }
    requireThat(peak > options.minimumMotion &&
      axialPeak > options.minimumMotion, `no ${axis}-axis wind response`);

    // 同一求解时刻的幅度变更与撤销；不仅检查参数，还检查几何位置。
    const saved = interaction.checkpoint();
    const before = anchors.position(tipId);
    interaction.rollbackAmplitude({ gain: 0, target: 0 });
    requireThat(anchors.position(tipId).distanceTo(initial) < 1e-7,
      'zero amplitude did not restore rest geometry');
    interaction.rollbackAmplitude(saved);
    requireThat(anchors.position(tipId).distanceTo(before) < 1e-7,
      'deformation amplitude rollback failed');
    anchors.assertFixed();

    for (let i = 0; i < Math.ceil(options.releaseSeconds / options.dt); i++) {
      frame(0);
    }
    const remaining = anchors.position(tipId).distanceTo(initial);
    requireThat(remaining <= peak * options.releaseFraction + 1e-7,
      `release did not settle on ${axis}`);
    result.push({ axis, peak, remaining });
  }
  return result;
}
```

集成边界：在导出器把命名节点写入资产之前调用 registerExportAnchors，并随资产交付其返回的 JSON 清单；加载后、首次风求解之前调用 bindBrowserAnchors 和 CampusManipulation。导出格式必须保留名称及 campus_anchor_id 元数据，否则绑定明确失败。这里新增的是可独立调用的接口，不声称已经修改了未提供路径的导出器或页面。
Drive 必须转接原有求解器；已提供源码仅能证明固定 windWorld 对应的风响应，不能证明存在横向方向设置接口。不得把 axis 参数静默忽略：若没有真实的横向驱动适配器，传入 z 时必须抛错并阻止实景验收。原始 stats.maxTipCm 仍代表求解结果，不代表显示包络后的位移；UI 应改用注册锚点的世界位置差显示最终变形幅度。

