```ts
import test from 'node:test';
import assert from 'node:assert/strict';
import * as THREE from 'three';
import {
  Anchor, Drive, boundedResponse, registerExportAnchors,
  bindBrowserAnchors, CampusManipulation, verifyCampusMotion
} from '../lib/campus-anchors.js';

// 这些名称是测试资产名称，不冒充基线中的真实节点 ID。
const manifest: Anchor[] = [
  { id: 'test.lamp.base', nodeName: 'test_lamp_base',
    role: 'lampBase', point: [0, 0, 0] },
  { id: 'test.tree.base', nodeName: 'test_tree_base',
    role: 'trunkBase', point: [0, 0, 0] },
  { id: 'test.tree.tip', nodeName: 'test_foreground_joint',
    role: 'canopyTip', point: [0, 2, 0] }
];

function exportedFixture() {
  const root = new THREE.Group();
  const lamp = new THREE.Group(); lamp.name = manifest[0].nodeName;
  const trunk = new THREE.Group(); trunk.name = manifest[1].nodeName;
  const joint = new THREE.Group(); joint.name = manifest[2].nodeName;
  joint.userData.wind_joint = true;
  trunk.add(joint); root.add(lamp, trunk);
  const exportedManifest = registerExportAnchors(root, manifest);
  // 执行实际序列化/反序列化，而非在同一个对象上自证 ID 正确。
  const browser = new THREE.ObjectLoader().parse(
    JSON.parse(JSON.stringify(root.toJSON()))
  );
  return { root: browser, manifest: exportedManifest };
}

function makeRig() {
  const { root, manifest: exportedManifest } = exportedFixture();
  const anchors = bindBrowserAnchors(root, exportedManifest);
  const joint = root.getObjectByName('test_foreground_joint')!;
  let x = 0, z = 0;
  // 明确为契约夹具，不是现有梁求解器的替代实现。
  const drive: Drive = (dt, speed, _mass, axis) => {
    x = boundedResponse(x, axis === 'z' ? speed * 0.08 : 0, dt, 0.15);
    z = boundedResponse(z, axis === 'x' ? -speed * 0.08 : 0, dt, 0.15);
    joint.quaternion.setFromEuler(new THREE.Euler(x, 0, z));
  };
  return {
    root, anchors, tipId: 'test.tree.tip',
    interaction: new CampusManipulation(root, anchors, drive)
  };
}

test('bounded response: endpoints, nonpositive time and unequal partitions', () => {
  assert.equal(boundedResponse(2, 9, 0, 1), 2);
  assert.equal(boundedResponse(2, 9, -1, 1), 2);
  assert.equal(boundedResponse(2, 9, 1, 0), 2);
  assert.equal(boundedResponse(2, 9, 1, -1), 2);
  for (const [old, target] of [[-3, 7], [7, -3], [4, 4]]) {
    for (const dt of [1 / 120, 1 / 60, 1 / 30, 100]) {
      const v = boundedResponse(old, target, dt, 0.2);
      assert.ok(v >= Math.min(old, target) && v <= Math.max(old, target));
    }
  }
  const single = boundedResponse(0, 1, 1, 1);
  const split = boundedResponse(boundedResponse(0, 1, 0.5, 1), 1, 0.5, 1);
  assert.equal(single, 0.5);
  assert.ok(Math.abs(split - 5 / 9) < 1e-12);
});

test('action, release, transverse axis, fixed bases and amplitude rollback', () => {
  for (const dt of [1 / 30, 1 / 60, 1 / 120]) {
    assert.equal(verifyCampusMotion(makeRig, {
      dt, actionSeconds: 2, releaseSeconds: 10,
      minimumMotion: 1e-4, releaseFraction: 0.1
    }).length, 2);
  }
});

test('world/local inverse survives transformed parents; base drag is rejected', () => {
  const { root, anchors, interaction, tipId } = makeRig();
  root.position.set(3, 0, -2);
  root.rotation.y = 0.4;
  root.scale.set(1.2, 0.9, 0.8);
  const local = new THREE.Vector3(0.2, 2.1, -0.3);
  const world = anchors.toWorld(tipId, local);
  assert.ok(anchors.toLocal(tipId, world).distanceTo(local) < 1e-10);
  interaction.dragAmplitude(tipId, world, 0.5);
  assert.throws(() => interaction.dragAmplitude('test.lamp.base', world, 0.5),
    /not draggable/);
});

test('explicit failures: lost ID, duplicate name, base drift, missing transverse drive', () => {
  const f = exportedFixture();
  delete f.root.getObjectByName('test_lamp_base')!.userData.campus_anchor_id;
  assert.throws(() => bindBrowserAnchors(f.root, f.manifest), /ID mismatch/);

  const g = exportedFixture();
  const duplicate = new THREE.Group(); duplicate.name = 'test_tree_base';
  g.root.add(duplicate);
  assert.throws(() => bindBrowserAnchors(g.root, g.manifest), /one named node/);

  const rig = makeRig();
  rig.root.getObjectByName('test_tree_base')!.position.x += 0.001;
  assert.throws(() => rig.anchors.assertFixed(), /fixed base moved/);

  const h = exportedFixture();
  const anchors = bindBrowserAnchors(h.root, h.manifest);
  const unsupported: Drive = (_dt, _speed, _mass, axis) => {
    if (axis === 'z') throw new Error('transverse drive unsupported');
  };
  const interaction = new CampusManipulation(h.root, anchors, unsupported);
  assert.throws(() => interaction.tick(1 / 60, 1, 0, 'z'), /unsupported/);
});
```

实景验收必须再运行同一个 verifyCampusMotion：factory 每次加载全新导出资产及原梁求解器，绑定实际节点清单，并提供确实改变风向的 Drive。真实浏览器加载后的场景必须重新执行 bindBrowserAnchors，不能以 Three JSON 夹具通过替代真实导出格式通过。交付报告应包含两轴 peak/remaining、每帧固定基座断言、清单与资产哈希、浏览器加载结果，以及幅度清零/撤销前后的锚点位置。当前未提供这些实测结果。
